            "expected": "The prior state remains available, its checksum matches after restoration, and every smoke check passes.",
            "gate_id": "G-D-ROLLBACK"
          }
        ],
        "option": "D",
        "owner": "Migration program lead (individual assignee must be recorded at G-NAMED-OWNERS)",
        "phase": 1,
        "purpose": "Provide a time-bounded legacy-compatible bridge while preserving the prior state; do not treat D recovery readiness as established.",
        "rollback_triggers": [
          {
            "action": "Stop the D cutover, restore the checksummed legacy state, and escalate the unmet migration gate before any retry.",
            "check": "Measure rehearsal or cutover elapsed time and run the legacy-compatibility suite.",
            "condition": "Elapsed time or forecast exceeds 14 calendar days, or any legacy-compatibility check fails.",
            "trigger_id": "RB-D-MIGRATION"
          },
          {
            "action": "Block or stop D cutover and restore the preserved legacy state until ownership and recovery evidence are complete.",
            "check": "Verify the acknowledged-owner roster and execute the D recovery rehearsal.",
            "condition": "Either cleanup or recovery owner is absent or unacknowledged, or the recovery rehearsal fails.",
            "trigger_id": "RB-D-RECOVERY"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "Inspect B mounts and credential scopes, then attempt cross-workspace reads and use of an unscoped credential.",
            "expected": "All mounts are workspace-only, every credential is scoped, and both negative attempts are denied and logged.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Collect separate warm and cold B distributions in the representative phase-2 window, recording sample count, censoring and exclusions, and compare them with approved service thresholds.",
            "expected": "Warm and cold results are not pooled, all censoring and exclusions are reported, and each approved threshold is met before expansion.",
            "gate_id": "G-B-WINDOW"
          },
          {
            "check": "Rehearse D-to-B migration, validate workspace state, then restore the preserved D state and run the D smoke suite.",
            "expected": "Workspace validation passes, the D state restores with a matching checksum, and every D smoke check passes.",
            "gate_id": "G-B-ROLLBACK"
          },
          {
            "check": "Recheck the acknowledged cleanup and recovery owner roster immediately before B cutover.",
            "expected": "Both individually named owners remain assigned, authorized, and acknowledged.",
            "gate_id": "G-B-OWNERS"
          }
        ],
        "option": "B",
        "owner": "Execution-fabric operations lead (individual assignee must be recorded at G-B-OWNERS)",
        "phase": 2,
        "purpose": "Move from D to the B target only after isolation, representative-window, ownership, and rollback evidence passes; make no universal performance claim.",
        "rollback_triggers": [
          {
            "action": "Stop expansion, revoke affected credentials, preserve incident evidence, and restore the verified D bridge state.",
            "check": "Continuously inspect mount scope, credential scope, and denied cross-workspace probes during the canary and cutover window.",
            "condition": "Any mount crosses a workspace boundary, any credential is unscoped, or a cross-workspace probe succeeds.",
            "trigger_id": "RB-B-ISOLATION"
          },
          {
            "action": "Stop expansion and restore the verified D bridge state while collecting a new separated benchmark window.",
            "check": "Compare canary warm and cold results with the thresholds approved at G-B-WINDOW and audit censoring and exclusions.",
            "condition": "An approved threshold is breached, warm and cold samples are pooled, or censoring or an invalid-run exclusion is omitted.",
            "trigger_id": "RB-B-WINDOW"
          },
          {
            "action": "Block or reverse B cutover to the verified D bridge state until ownership and rollback evidence pass again.",
            "check": "Recheck named-owner acknowledgements and the latest B-to-D rollback rehearsal result.",
            "condition": "A required owner becomes unassigned or unacknowledged, or the rollback rehearsal fails.",
            "trigger_id": "RB-B-OPERATIONS"
          }
        ]
      }
    ],
    "strategy": "Use D as a time-bounded, gated legacy-compatible migration bridge, then target B after isolation, ownership, recovery, representative-window, and rollback gates; retain A only as a conditional warm-latency optimization and reject C's invalid pooled claim."
